206	/**
207	 * Boot-time arrival: finds a portal near the mapped anchor (1:1 coordinates)
208	 * or builds one — a stone pad with headroom, a lit 2×3 frame — and returns the
209	 * cell the player lands in (inside the portal, so the caller must latch their
210	 * dwell). Runs BEFORE the full light bake; every write rides `blockChanges`,
211	 * so the built portal persists as ordinary diff.
212	 */
213	export function ensureArrivalPortal(
214	  world: VoxelWorld,
215	  blockChanges: BlockChangeTracker,
216	  floorYAt: SurfaceYAtFn,
217	  anchor: { x: number; y: number; z: number }
218	): { x: number; y: number; z: number } {
219	  // Reuse: the nearest existing portal surface inside the search box wins.
220	  const minX = Math.max(1, anchor.x - PORTAL_SEARCH_RADIUS);
221	  const maxX = Math.min(world.sizeX - 2, anchor.x + PORTAL_SEARCH_RADIUS);
222	  const minZ = Math.max(1, anchor.z - PORTAL_SEARCH_RADIUS);
223	  const maxZ = Math.min(world.sizeZ - 2, anchor.z + PORTAL_SEARCH_RADIUS);
224	  let best: { x: number; y: number; z: number } | null = null;
225	  let bestDist = Infinity;
226	  for (let x = minX; x <= maxX; x += 1) {
227	    for (let z = minZ; z <= maxZ; z += 1) {
228	      for (let y = 1; y < world.sizeY - 1; y += 1) {
229	        if (world.get(x, y, z) !== BlockId.NetherPortal) continue;
230	        while (y > 1 && world.get(x, y - 1, z) === BlockId.NetherPortal) y -= 1; // its lowest cell
231	        const dist = Math.hypot(x - anchor.x, z - anchor.z);
232	        if (dist < bestDist) {
233	          bestDist = dist;
234	          best = { x, y, z };
235	        }
236	        break; // one hit per column is enough
237	      }
238	    }
239	  }
240	  if (best) return best;
241	
242	  // Build: a 6×3 stone pad with 5 cells of headroom, a lit frame at its edge.
243	  const bx = Math.max(4, Math.min(world.sizeX - 6, anchor.x));
244	  const bz = Math.max(4, Math.min(world.sizeZ - 6, anchor.z));
245	  let by = Math.floor(floorYAt(bx, bz));
246	  if (by <= 2 || by >= world.sizeY - 8) by = Math.max(3, Math.min(world.sizeY - 8, Math.floor(world.sizeY / 3)));
247	  for (let dx = -2; dx <= 3; dx += 1) {
248	    for (let dz = -1; dz <= 1; dz += 1) {
249	      blockChanges.set(bx + dx, by - 1, bz + dz, BlockId.Stone);
250	      for (let dy = 0; dy <= 4; dy += 1) blockChanges.set(bx + dx, by + dy, bz + dz, BlockId.Air);
251	    }
252	  }
253	  for (let i = -1; i <= 2; i += 1) {
254	    blockChanges.set(bx + i, by - 1, bz, BlockId.Obsidian);
255	    blockChanges.set(bx + i, by + 3, bz, BlockId.Obsidian);
256	  }
257	  for (let j = 0; j < 3; j += 1) {
258	    blockChanges.set(bx - 1, by + j, bz, BlockId.Obsidian);
259	    blockChanges.set(bx + 2, by + j, bz, BlockId.Obsidian);
260	  }
261	  for (let i = 0; i < 2; i += 1) {
262	    for (let j = 0; j < 3; j += 1) blockChanges.set(bx + i, by + j, bz, BlockId.NetherPortal);
263	  }
264	  return { x: bx, y: by, z: bz };
265	}
