241	function aimAt(player: PlayerState, tx: number, ty: number, tz: number): void {
242	  const eye = new THREE.Vector3(player.position.x, player.position.y + EYE_HEIGHT, player.position.z);
243	  const dir = new THREE.Vector3(tx, ty, tz).sub(eye).normalize();
244	  player.pitch = Math.asin(dir.y);
245	  player.yaw = Math.atan2(-dir.x, -dir.z);
246	}
