1	import { describe, expect, test } from "bun:test";
2	import { GameEngine } from "@/lib/game/engine/GameEngine";
3	import { pushMob } from "@/lib/game/engine/systems/spawnDirector";
4	import type { Difficulty } from "@/lib/game/difficulties";
5	
6	function mulberry32(seed: number): () => number {
7	  let t = seed >>> 0;
8	  return () => {
9	    t += 0x6d2b79f5;
10	    let r = Math.imul(t ^ (t >>> 15), 1 | t);
11	    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
12	    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
13	  };
14	}
15	
16	function makeEngine(difficulty: Difficulty): GameEngine {
17	  return new GameEngine({ seed: 1337, difficulty, rng: mulberry32(42), worldSize: { x: 64, y: 150, z: 64 } });
18	}
19	
20	/**
21	 * Replaces the constructor's initial spawn with a fixed mix of two hostiles and
22	 * two passives near the player, so the assertions count exactly what we seeded.
23	 */
24	function seedMobs(e: GameEngine): void {
25	  e.state.mobs = [];
26	  const { x, y, z } = e.state.player.position;
27	  const rng = mulberry32(7);
28	  pushMob(e.state, "zombie", true, x + 4, y, z, rng);
29	  pushMob(e.state, "skeleton", true, x - 4, y, z + 2, rng);
30	  pushMob(e.state, "sheep", false, x + 2, y, z - 3, rng);
31	  pushMob(e.state, "cow", false, x - 2, y, z + 3, rng);
32	}
33	
34	describe("setDifficulty", () => {
35	  test("switching to Peaceful despawns every hostile but keeps passives", () => {
36	    const e = makeEngine("normal");
37	    seedMobs(e);
38	    expect(e.state.mobs.some((m) => m.hostile)).toBe(true);
39	
40	    e.dispatch({ type: "setDifficulty", difficulty: "peaceful" });
41	
42	    expect(e.state.difficulty).toBe("peaceful");
43	    expect(e.state.mobs.some((m) => m.hostile)).toBe(false);
44	    expect(e.state.mobs.filter((m) => !m.hostile)).toHaveLength(2); // sheep + cow survive
45	  });
46	
47	  test("the Peaceful despawn rewards nothing and never counts as a boss victory", () => {
48	    const e = makeEngine("hard");
49	    e.state.mobs = [];
50	    const rng = mulberry32(7);
51	    const { x, y, z } = e.state.player.position;
52	    pushMob(e.state, "boss", true, x + 5, y, z, rng);
53	    pushMob(e.state, "zombie", true, x - 5, y, z, rng);
54	    const xpBefore = e.state.xp;
55	
56	    e.dispatch({ type: "setDifficulty", difficulty: "peaceful" });
57	
58	    expect(e.state.mobs).toHaveLength(0);
59	    expect(e.state.victory).toBe(false); // despawning the boss is not defeating it
60	    expect(e.state.xp).toBe(xpBefore); // no kill XP for a despawn
61	  });
62	
63	  test("a same-difficulty switch is a no-op that leaves hostiles alone", () => {
64	    const e = makeEngine("normal");
65	    seedMobs(e);
66	    e.dispatch({ type: "setDifficulty", difficulty: "normal" });
67	    expect(e.state.mobs.some((m) => m.hostile)).toBe(true); // untouched
68	  });
69	
70	  test("raising Peaceful → Hard sets the level without instantly spawning a horde", () => {
