1	import type { Command } from "@/lib/game/engine/commands";
2	import type { GameEvent } from "@/lib/game/engine/state";
3	import { ENCHANTMENT_DEFS } from "@/lib/game/enchantments";
4	import type { EnchantmentId, SavedContainer, SavedMob, SavedPlayer, SavedStat } from "@/lib/game/types";
5	
6	/**
7	 * The client↔game-server wire protocol. Versioned as a whole: a client built
8	 * against a different PROTOCOL_VERSION is refused at the door (its join
9	 * ticket carries the number), so mid-session format drift can't happen.
10	 *
11	 * v1 is JSON envelopes discriminated on `t`, except the one big payload —
12	 * the join world-sync — which travels as a gzipped binary frame (see
13	 * codec.ts). The envelope layout deliberately leaves room to move the hot
14	 * paths (pose/tick) to packed binary later without renegotiating anything.
15	 *
16	 * Validation is hand-rolled and TOTAL (the save.ts house style): the server
17	 * feeds hostile bytes through these readers and gets a typed message or
18	 * null — never an exception, never a partially-checked object.
19	 */
20	export const PROTOCOL_VERSION = 3;
21	
22	// ── close codes (WebSocket application range) ────────────────────────────────
23	export const CLOSE_BAD_TICKET = 4000;
24	export const CLOSE_PROTOCOL_MISMATCH = 4001;
25	export const CLOSE_ROOM_FULL = 4002;
26	export const CLOSE_KICKED = 4003;
27	export const CLOSE_IDLE_TIMEOUT = 4004;
28	export const CLOSE_SERVER_SHUTDOWN = 4005;
29	export const CLOSE_SLOW_CLIENT = 4008;
30	
31	/** Max players per room (the v1 co-op scale the whole design assumes). */
32	export const ROOM_CAPACITY = 8;
33	
34	/**
35	 * Reconnect back-off ladder (ms between attempts). A dropped socket that isn't
36	 * a fatal close walks this once — five tries over ~23 s — before the client
37	 * gives up and shows the disconnect modal.
38	 */
39	export const RECONNECT_DELAYS_MS = [1000, 2000, 4000, 8000, 8000] as const;
40	
41	// ── client → server ──────────────────────────────────────────────────────────
42	
43	/** First frame on the socket: the join ticket (minted by the web API) + the client's protocol. */
44	export type HelloMessage = { t: "hello"; ticket: string; protocol: number };
45	
46	/** The client-authoritative avatar pose, streamed at tick rate. */
47	export type PoseMessage = {
48	  t: "pose";
49	  seq: number;
50	  x: number;
51	  y: number;
52	  z: number;
53	  yaw: number;
54	  pitch: number;
55	  onGround: boolean;
56	  /** The player's live movement intents (server systems read them for vehicles etc.). */
57	  move: { forward: boolean; back: boolean; left: boolean; right: boolean; jump: boolean; sprint: boolean; crouch: boolean };
58	  mineHeld: boolean;
59	};
60	
61	/**
62	 * A discrete command. Carries the client's claimed eye pose at click time:
63	 * the server applies it (sanity-checked like any pose) before dispatch, so
64	 * aimed raycasts (attack/placeBlock) resolve against the server's world from
65	 * where the client actually looked. `view` (v3) is the client's render-time
66	 * view of the world — ms on the server tick timeline (`tick × 50`), i.e. the
67	 * instant the interpolated mobs on its screen were sampled at — letting the
68	 * server rewind melee target selection to what the player saw. Absent while
69	 * the clock isn't synced; the server clamps it, never trusts it.
70	 */
71	export type CmdMessage = { t: "cmd"; seq: number; cmd: Command; pose: { x: number; y: number; z: number; yaw: number; pitch: number }; view?: number };
72	
73	export type ChatMessage = { t: "chat"; text: string };
74	export type PingMessage = { t: "ping"; id: number; tMs: number };
75	/** Ask for a fresh world-sync + mob keyframe (reconnect resume). */
76	export type ResyncMessage = { t: "resync" };
77	/** Owner-only: eject a player from the world. Ignored from a non-owner (server re-checks the ticket role). */
78	export type KickMessage = { t: "kick"; targetId: string };
79	
80	export type ClientMessage = HelloMessage | PoseMessage | CmdMessage | ChatMessage | PingMessage | ResyncMessage | KickMessage;
81	
82	// ── server → client ──────────────────────────────────────────────────────────
83	
84	export type RosterEntry = { id: string; name: string; skinId: string | null; x: number; y: number; z: number; yaw: number };
85	
86	export type WelcomeMessage = {
87	  t: "welcome";
88	  protocol: number;
89	  playerId: string;
90	  worldId: string;
91	  seed: number;
92	  worldType: string;
93	  difficulty: string;
94	  hardcore: boolean;
95	  dayClock: number;
96	  tick: number;
97	  /** The recipient's own role in this world (from the join ticket) — gates the in-game owner controls. */
98	  role: "owner" | "member";
99	  players: RosterEntry[];
100	};
101	
102	/**
103	 * The join payload (sent as ONE gzipped binary frame right after welcome):
104	 * everything a client can't regenerate from the seed. Mirrors the v17 save's
105	 * world half plus the live session entities.
106	 */
107	export type WorldSync = {
108	  t: "worldSync";
109	  tick: number;
110	  dayClock: number;
111	  changes: Array<[number, number]>;
112	  blockEntities: SavedContainer[];
113	  lootedChests: number[];
114	  mobs: SavedMob[];
115	  liveMobs: MobPose[];
116	  /** Live vehicles keyed by server id (poses, not the SavedVehicle save shape) so per-tick `vp` deltas line up. */
117	  vehicles: VehiclePose[];
118	  /** In-flight arrows at join time (usually empty — arrows are short-lived). */
119	  projectiles: ProjectilePose[];
120	  players: RosterEntry[];
121	};
122	
123	/** One mob's replicated pose (10 Hz, deadbanded; keyframed every ~5s). */
124	export type MobPose = { id: number; kind: string; hostile: boolean; x: number; y: number; z: number; yaw: number; hp: number; moveSpeed: number };
125	
126	/** One vehicle's replicated pose (deadbanded per tick). `riderId` is cosmetic on the client (the server owns mounted motion). */
127	export type VehiclePose = { id: number; kind: string; x: number; y: number; z: number; yaw: number; riderId: string | null };
128	
129	/**
130	 * One arrow's replicated pose. Velocity travels so the client orients the mesh
131	 * from it (projectileVisuals derives yaw/pitch from velocity, unchanged). Arrows
132	 * are fast and short-lived, so they snap per frame — no interpolation buffer.
133	 */
134	export type ProjectilePose = { id: number; x: number; y: number; z: number; vx: number; vy: number; vz: number };
135	
136	/** One player's replicated pose (20 Hz). */
137	export type PlayerPose = { id: string; x: number; y: number; z: number; yaw: number; pitch: number };
138	
139	/**
140	 * The per-player private delta: the server-authoritative mirror of what the
141	 * SP snapshot shows about YOU. Only changed fields are present.
142	 */
143	export type SelfDelta = {
144	  inventorySlots?: SavedPlayer["inventorySlots"];
145	  equippedArmor?: SavedPlayer["equippedArmor"];
146	  selectedSlot?: number;
147	  hearts?: number;
148	  hunger?: number;
149	  oxygen?: number;
150	  xp?: number;
151	  effects?: SavedPlayer["effects"];
152	  isDead?: boolean;
153	  respawnSeconds?: number;
154	  gameMode?: string;
155	  sleeping?: boolean;
156	  /** The recipient's unlocked advancement ids (full set, sent when it grows). */
157	  advancements?: string[];
158	  /** Event-driven stat counters that changed (the two continuous display stats — play_time/distance_walked — accrue client-side). */
159	  stats?: SavedStat[];
160	  /**
161	   * Which vehicle the recipient is riding (id), or null when they dismount.
162	   * Present only on the tick the mount state changes. While it is non-null the
163	   * server owns the rider's position: `x`/`y`/`z` below carry that authoritative
164	   * position (the client snaps to it and skips its own motion integration).
165	   */
166	  mountedVehicleId?: number | null;
167	  x?: number;
168	  y?: number;
169	  z?: number;
170	};
171	
172	export type TickMessage = {
173	  t: "tick";
174	  n: number;
175	  /** Block writes this tick as [voxelIndex, blockId] — the replica's world mutation channel. */
176	  blocks?: Array<[number, number]>;
177	  /** Attributed world events since the last tick (block edits ride these). */
178	  ev: Array<GameEvent & { playerId?: string }>;
179	  /** Other players' poses (the recipient's own is omitted). */
180	  pp: PlayerPose[];
181	  /** Mob poses that moved past the deadband this window (10 Hz). */
182	  mp: MobPose[];
183	  /** Vehicle poses that moved past the deadband this tick (absent when nothing moved). */
184	  vp?: VehiclePose[];
185	  /** Every live arrow this tick (the full authoritative list — absence prunes); one empty frame signals the last arrow cleared. */
186	  prj?: ProjectilePose[];
187	  /** Day clock, every ~20 ticks (clients advance it locally in between). */
188	  day?: number;
189	  /** The recipient's private state changes. */
190	  self?: SelfDelta;
191	};
192	
193	export type MobsKeyframeMessage = { t: "mobsKeyframe"; n: number; mobs: MobPose[] };
194	export type PlayerJoinedMessage = { t: "playerJoined"; player: RosterEntry };
195	export type PlayerLeftMessage = { t: "playerLeft"; id: string };
196	export type ContainerMessage = { t: "container"; index: number; slots: SavedContainer["slots"] };
197	export type ChatBroadcastMessage = { t: "chat"; from: string; name: string; text: string };
198	export type PongMessage = { t: "pong"; id: number; tMs: number; serverTick: number };
199	/** Position correction: the client must snap its avatar here (failed pose sanity check). */
200	export type ForcePoseMessage = { t: "forcePose"; x: number; y: number; z: number; yaw: number; pitch: number };
201	
202	export type ServerMessage =
203	  | WelcomeMessage
204	  | TickMessage
205	  | MobsKeyframeMessage
206	  | PlayerJoinedMessage
207	  | PlayerLeftMessage
208	  | ContainerMessage
209	  | ChatBroadcastMessage
210	  | PongMessage
211	  | ForcePoseMessage;
212	
213	// ── validators (client → server only: the server is the hostile-input side) ──
214	
215	const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
216	const isBool = (v: unknown): v is boolean => typeof v === "boolean";
217	const isStr = (v: unknown): v is string => typeof v === "string";
218	
219	function readMove(v: unknown): PoseMessage["move"] | null {
220	  if (!v || typeof v !== "object") return null;
221	  const m = v as Record<string, unknown>;
222	  const keys = ["forward", "back", "left", "right", "jump", "sprint", "crouch"] as const;
223	  const out = {} as Record<(typeof keys)[number], boolean>;
224	  for (const key of keys) {
225	    if (!isBool(m[key])) return null;
226	    out[key] = m[key] as boolean;
227	  }
228	  return out;
229	}
230	
231	function readEyePose(v: unknown): CmdMessage["pose"] | null {
232	  if (!v || typeof v !== "object") return null;
233	  const p = v as Record<string, unknown>;
234	  if (!isNum(p.x) || !isNum(p.y) || !isNum(p.z) || !isNum(p.yaw) || !isNum(p.pitch)) return null;
235	  return { x: p.x, y: p.y, z: p.z, yaw: p.yaw, pitch: p.pitch };
236	}
237	
238	/**
239	 * Command allow-list: every dispatchable type with per-field checks. Unknown
240	 * or malformed commands are dropped here — dispatch never sees them. Local-
241	 * presentation commands (pause/debug/camera) are deliberately absent: they
242	 * have no business on a wire.
243	 */
244	export function readCommand(v: unknown): Command | null {
245	  if (!v || typeof v !== "object") return null;
